  "oasOpening": {
    "speaker": "Julian",
    "text": "You glanced toward me three times during the invocation, fingers tightening on the sash each time Seren faltered. Did you shape her wish without knowing it, the way you shape everyone’s attention, hoping I would step forward and rescue you?"
  },
  "postInterruptionBeat": {
    "speaker": "Lirael",
    "image": "d4",
    "kind": "narration",
    "text": "The Answer rested in my hands, still warm from Julian’s grip, while the presiding Dohkar’s voice cut the air and the clearing fell silent around the two of us. The formal inquiry he had just invoked loomed, and I had no idea whether answering or staying silent would protect what remained of my path."
  },
  "fateCards": {
    "temptation": {"action": "Lean closer and meet Julian’s eyes directly", "dialogue": "Then ask me what you truly want to know.", "variant": "amplify"},
    "silence": {"action": "Lower my gaze and hold The Answer without speaking", "dialogue": "(soft exhale)", "variant": "amplify"},
    "reversal": {"action": "Turn the stone slightly toward the Dohkar", "dialogue": "Perhaps the inquiry should examine who benefits from these charges.", "variant": "redirect"},
    "boundary": {"action": "Step back one pace while keeping the stone raised", "dialogue": "I will answer only in the formal setting you have claimed.", "variant": "amplify"},
    "confession": {"action": "Lift my chin and speak the next words plainly", "dialogue": "I did watch you. That part is true.", "variant": "ruin"}
  }
